<h2>Calculate prorated rent</h2><p class="lead">Prorate monthly rent using actual calendar days or a 30-day convention.</p><div class="notice">Actual-days and 30-day conventions can produce different amounts. This tool makes the denominator explicit rather than assuming one method is legally correct.</div><div class="form-grid"><div class="field"><label for="rent">Monthly rent</label><input id="rent" type="number" value="30000" min="0" step="any"></div><div class="field"><label for="days">Chargeable occupancy days</label><input id="days" type="number" value="12" min="0" step="1"></div><div class="field"><label for="monthdays">Days in calendar month</label><input id="monthdays" type="number" value="30" min="28" max="31" step="1"></div><div class="field"><label for="method">Proration convention</label><select id="method"><option value="actual" selected>Actual days in month</option><option value="30">30-day month</option></select></div></div><div class="tool-actions"><button class="btn btn-primary" id="calc" type="button">Calculate</button><button class="btn btn-secondary" id="reset" type="button">Reset</button></div><div class="result-box"><div class="result-grid"><div class="metric"><span>Daily rent rate</span><strong id="daily">—</strong></div><div class="metric"><span>Prorated rent</span><strong id="prorated">—</strong></div><div class="metric"><span>Share of month charged</span><strong id="pct">—</strong></div><div class="metric"><span>Uncharged monthly rent</span><strong id="remaining">—</strong></div></div><div id="note" class="helper" style="margin-top:12px"></div></div><script>
(()=>{
const $=id=>document.getElementById(id); const num=id=>Number($(id).value); const fmt=(v,d=2)=>Number.isFinite(v)?v.toLocaleString(undefined,{maximumFractionDigits:d}):'—';
const defaults={}; document.querySelectorAll('.tool-panel input,.tool-panel select,.tool-panel textarea').forEach(el=>defaults[el.id]=el.value);
function clear(){$('daily').textContent='—';$('prorated').textContent='—';$('pct').textContent='—';$('remaining').textContent='—'; const n=$('note'); if(n){n.textContent='';n.className='helper';}}
function calculate(){try{const r=num('rent'),d=num('days'),md=num('monthdays'),m=$('method').value;const den=m==='30'?30:md;if(!(r>=0&&d>=0&&den>0&&d<=den))throw 0;const daily=r/den,amt=daily*d;$('daily').textContent=fmt(daily,2);$('prorated').textContent=fmt(amt,2);$('pct').textContent=fmt(d/den*100,2)+'%';$('remaining').textContent=fmt(r-amt,2);$('note').textContent='Lease language and local law determine the permitted proration method. Use the convention stated in the agreement or required in your jurisdiction.';}catch(e){clear(); const n=$('note'); if(n){n.textContent='Please check the inputs and try again.';n.className='helper danger';}}}
const c=$('calc'); if(c)c.addEventListener('click',calculate); const r=$('reset'); if(r)r.addEventListener('click',()=>{Object.entries(defaults).forEach(([id,v])=>{if($(id))$(id).value=v});calculate();});
document.querySelectorAll('.tool-panel input,.tool-panel select,.tool-panel textarea').forEach(el=>el.addEventListener('input',calculate));
calculate();
})();
</script>
